import { test } from '@playwright/test';
import { DOCS, backButton, expectDocOpen, visibleText } from './legal-docs.helpers';

test.use({ storageState: { cookies: [], origins: [] } });

test.describe('Юридические документы — гость (регресс ссылок регистрации)', () => {
  for (const doc of ['terms', 'privacy'] as const) {
    const d = DOCS[doc];
    test(`Гость: «${d.title}» из регистрации открывается, «→ חזרה» возвращает на /sign-up @desktop @prod-safe #d7fe2c`, async ({ page }) => {
      await page.goto('/sign-up');
      // F-15: регистрация требует согласия с условиями и политикой; #f8756c
      await visibleText(page, d.title).click();
      await page.waitForURL(d.urlRe);
      await expectDocOpen(page, doc);

      await backButton(page).click();
      await page.waitForURL(/\/sign-up$/);
    });
  }
});
